def inject(path, marker, block):
    text = path.read_text()
    if 'SEPT11_EDITORIAL_START' in text:
        return
    if marker not in text:
        raise SystemExit(f'Marker not found in {path}: {marker}')
    path.write_text(text.replace(marker, marker + '\n' + block, 1))

